import{PlatformError}from'../../foundation/errors/platform-error.js';import{DebuggingDiagnosticsTracingSupportBundlesProfile as P}from'../contracts/debugging-diagnostics-tracing-support-bundles-profile.js';import*as c from'../debugging-diagnostics-tracing-support-bundles-constants.js';const M=Object.freeze({logFields:c.DIAGNOSTICS_LOG_FIELDS,traceFields:c.DIAGNOSTICS_TRACE_FIELDS,healthCheckFields:c.DIAGNOSTICS_HEALTH_CHECK_FIELDS,explainPlanFields:c.DIAGNOSTICS_EXPLAIN_PLAN_FIELDS,redactionFields:c.DIAGNOSTICS_REDACTION_FIELDS,supportBundleFields:c.DIAGNOSTICS_SUPPORT_BUNDLE_FIELDS,correlationRemediationFields:c.DIAGNOSTICS_CORRELATION_REMEDIATION_FIELDS,controls:c.DIAGNOSTICS_CONTROLS,failureRecovery:c.DIAGNOSTICS_RECOVERY,observabilityFields:c.DIAGNOSTICS_OBSERVABILITY,assuranceEvidence:c.DIAGNOSTICS_ASSURANCE,invariants:c.DIAGNOSTICS_INVARIANTS});const R={logsRedacted:'requires secret and classified field redaction before logs are written',correlationPropagated:'requires a correlation identifier surfaced in output logs traces and errors',bundlesScrubbed:'requires a mandatory redaction and scrub pass before support bundle packaging',healthChecksAvailable:'requires environment dependency and readiness health checks',remediationGuided:'requires ordered guided remediation steps for common failures',contextExplained:'requires an explain plan of resolved context and planned actions'};const N={diagnosticsGrantAuthority:'prohibits diagnostics or support bundles granting tooling production or cross-tenant authority',secretsInLogs:'prohibits secrets or classified values in logs or traces',secretsInSupportBundle:'prohibits secrets tokens source code or customer data in support bundles',bundleSharedWithoutConsent:'prohibits creating or sharing a support bundle without explicit user consent',customerDataInDiagnostics:'prohibits source code request/response payloads or customer data in diagnostics',aiSilentlyRemediates:'prohibits AI assistance silently applying remediation',correlationIdMissing:'prohibits invocations without a surfaced correlation identifier',staleDiagnosticsUnlabeled:'prohibits stale diagnostics or cached results without freshness labelling',hiddenPartialFailure:'prohibits hidden partial failure'};export class DebuggingDiagnosticsTracingSupportBundlesDescriptor{logFields(){return v(M.logFields)}traceFields(){return v(M.traceFields)}healthCheckFields(){return v(M.healthCheckFields)}explainPlanFields(){return v(M.explainPlanFields)}redactionFields(){return v(M.redactionFields)}supportBundleFields(){return v(M.supportBundleFields)}correlationRemediationFields(){return v(M.correlationRemediationFields)}controls(){return v(M.controls)}failureRecovery(){return v(M.failureRecovery)}observabilityFields(){return v(M.observabilityFields)}assuranceEvidence(){return v(M.assuranceEvidence)}invariants(){return v(M.invariants)}validateProfile(x){const p=x instanceof P?x:new P(x),e=[];if(!p.profileName)e.push('Debugging Diagnostics Tracing and Support Bundles profile must have a name.');for(const[k,s]of Object.entries(M))for(const a of v(s))if(!p[k].includes(a))e.push(`${k} must include ${a}.`);for(const[k,m]of Object.entries(R))if(!p[k])e.push(`ARCH-035-07 ${m}.`);for(const[k,m]of Object.entries(N))if(p[k])e.push(`ARCH-035-07 ${m}.`);return Object.freeze({isValid:!e.length,errors:Object.freeze(e)})}assertArchitecture(){const e=[];for(const[k,s]of Object.entries(M))if(this[k]().length!==Object.keys(s).length)e.push(`${k} is incomplete.`);if(e.length)throw new PlatformError(c.DEBUGGING_DIAGNOSTICS_TRACING_SUPPORT_BUNDLES_ERROR_CODE,'Debugging Diagnostics Tracing and Support Bundles violates ARCH-035-07.',{errors:e});return Object.freeze({isValid:true,errors:Object.freeze([])})}}function v(s){return Object.freeze(Object.values(s))}
